// Bakes the vocabulary the browser needs into two generated files (pattern from Nihongo Explorer):
//   vocab-runtime.js          list fields of every entry, in the order the app shows them
//   vocab-runtime-details.js  examples and notes per entry, loaded in the background
// The per-level source files stay the input for the tools and audits.
// Usage: node scripts/build-vocab-runtime.cjs [--check]
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const ROOT = path.resolve(__dirname, '..');
const RUNTIME_FILE = 'vocab-runtime.js';
const DETAILS_FILE = 'vocab-runtime-details.js';
const DETAIL_FIELDS = ['examples', 'notes'];
// Provenance needed by the audits only.
const DROPPED_FIELDS = new Set(['syllabus', 'evidence', 'evidenceNote', 'review']);
const HEADER = '// Generated by scripts/build-vocab-runtime.cjs from the vocabulary sources. Do not edit; run npm run build:vocab-runtime.\n';

function loadEntries(readFile) {
  const context = { console };
  context.window = context;
  vm.runInNewContext(readFile('lang-profile.js'), context, { filename: 'lang-profile.js' });
  const profile = context.LANG_PROFILE;
  for (const file of profile.dataScripts.vocab) vm.runInNewContext(readFile(file), context, { filename: file });
  // Same order as the former loader: levels, Zusatz, then the specialist lists.
  const items = [];
  profile.levels.concat([profile.extraLevel]).forEach(level => {
    items.push(...(context['VOCAB_' + level.replace('-', '_').toUpperCase()] || []));
  });
  items.push(...(context.CHENGYU_DATA || []), ...(context.REDEWENDUNGEN_DATA || []));
  return items;
}

function splitItem(item) {
  const core = {}, details = {};
  for (const key of Object.keys(item)) {
    if (DROPPED_FIELDS.has(key) || item[key] === undefined) continue;
    if (DETAIL_FIELDS.includes(key)) details[key] = item[key];
    else core[key] = item[key];
  }
  return { core, details };
}

// One entry per line keeps git diffs readable.
const lines = values => values.map(value => JSON.stringify(value)).join(',\n');

function buildVocabRuntime(readFile = file => fs.readFileSync(path.join(ROOT, file), 'utf8')) {
  const parts = loadEntries(readFile).map(splitItem);
  return {
    [RUNTIME_FILE]: HEADER + 'window.VOCAB_RUNTIME = {\n"items": [\n' + lines(parts.map(p => p.core)) + '\n]};\n',
    [DETAILS_FILE]: HEADER + '// Entries align by index with VOCAB_RUNTIME.items.\nwindow.VOCAB_RUNTIME_DETAILS = [\n' + lines(parts.map(p => p.details)) + '\n];\n'
  };
}

// A Windows checkout (core.autocrlf) may hold the generated files with CRLF line endings.
function staleFiles(files) {
  return Object.keys(files).filter(file => {
    const target = path.join(ROOT, file);
    return !fs.existsSync(target) || fs.readFileSync(target, 'utf8').replace(/\r\n/g, '\n') !== files[file];
  });
}

function writeVocabRuntime() {
  const files = buildVocabRuntime();
  const stale = staleFiles(files);
  for (const file of stale) fs.writeFileSync(path.join(ROOT, file), files[file]);
  return stale;
}

function main(args) {
  if (args.includes('--check')) {
    const files = buildVocabRuntime();
    const stale = staleFiles(files);
    if (stale.length) {
      console.error('Stale generated vocabulary runtime: ' + stale.join(', ') + '. Run npm run build:vocab-runtime.');
      process.exit(1);
    }
    console.log('Vocabulary runtime is up to date (' + Object.keys(files).join(', ') + ').');
    return;
  }
  const stale = writeVocabRuntime();
  console.log(stale.length ? 'Wrote ' + stale.join(', ') : 'Vocabulary runtime already up to date.');
}

if (require.main === module) main(process.argv.slice(2));
module.exports = { RUNTIME_FILE, DETAILS_FILE, buildVocabRuntime, writeVocabRuntime };
